def investigate(context, acquire):
    receipts = acquire("history")
    # Family: put mode in {ignore, replace, upsert}, trigger in {none, after_insert},
    # channel in {changes, total_main, total_main+total_other}
    # We simulate each candidate and keep those matching all receipts.

    def simulate(actions, mode, trig, chan):
        # state: dict key->value for committed items
        # We track per-connection total_changes and last changes()
        state = {}
        # transaction buffers per connection
        tx = {"main": None, "other": None}
        total = {"main": 0, "other": 0}
        last_changes = {"main": 0, "other": 0}
        log_count = 0

        def apply_write(conn, op, key, value):
            nonlocal log_count
            # returns number of direct row changes for this statement
            if op == "put":
                if mode == "ignore":
                    if key in state:
                        return 0
                    state[key] = value
                    n = 1
                elif mode == "replace":
                    state[key] = value
                    n = 1
                else:  # upsert
                    if key in state:
                        state[key] = value
                        n = 1
                    else:
                        state[key] = value
                        n = 1
                if trig and n > 0:
                    log_count += 1
                return n
            elif op == "update":
                if key in state:
                    state[key] = value
                    n = 1
                else:
                    n = 0
                if trig and n > 0:
                    log_count += 1
                return n
            elif op == "delete":
                if key in state:
                    del state[key]
                    n = 1
                else:
                    n = 0
                return n
            return 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                tx[conn] = dict(state)
            elif op == "commit":
                if tx[conn] is not None:
                    state = tx[conn]
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            else:
                key = act.get("key")
                value = act.get("value", 0)
                if tx[conn] is not None:
                    # operate on tx buffer
                    saved = state
                    state = tx[conn]
                    n = apply_write(conn, op, key, value)
                    tx[conn] = state
                    state = saved
                else:
                    n = apply_write(conn, op, key, value)
                total[conn] += n
                last_changes[conn] = n

        if chan == "changes":
            return last_changes["main"]
        elif chan == "total_main":
            return total["main"]
        else:
            return total["main"] + total["other"]

    modes = ["ignore", "replace", "upsert"]
    trigs = [False, True]
    chans = ["changes", "total_main", "total_both"]

    candidates = []
    for mode in modes:
        for trig in trigs:
            for chan in chans:
                ok = True
                for r in receipts:
                    acts = r.get("actions", [])
                    obs = r.get("observed", {})
                    ch = simulate(acts, mode, trig, chan)
                    if ch != obs.get("channel"):
                        ok = False
                        break
                    # committed state check
                    st = {}
                    tx = {"main": None, "other": None}
                    for act in acts:
                        op = act.get("op")
                        conn = act.get("connection", "main")
                        if op == "begin":
                            tx[conn] = dict(st)
                        elif op == "commit":
                            if tx[conn] is not None:
                                st = tx[conn]
                                tx[conn] = None
                        elif op == "rollback":
                            tx[conn] = None
                        else:
                            key = act.get("key")
                            value = act.get("value", 0)
                            if tx[conn] is not None:
                                saved = st
                                st = tx[conn]
                                if op == "put":
                                    if mode == "ignore":
                                        if key not in st:
                                            st[key] = value
                                    else:
                                        st[key] = value
                                elif op == "update":
                                    if key in st:
                                        st[key] = value
                                elif op == "delete":
                                    if key in st:
                                        del st[key]
                                tx[conn] = st
                                st = saved
                            else:
                                if op == "put":
                                    if mode == "ignore":
                                        if key not in st:
                                            st[key] = value
                                    else:
                                        st[key] = value
                                elif op == "update":
                                    if key in st:
                                        st[key] = value
                                elif op == "delete":
                                    if key in st:
                                        del st[key]
                    if len(st) != obs.get("committed_count"):
                        ok = False
                        break
                    if sum(st.values()) != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((mode, trig, chan))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])

    results = set()
    for mode, trig, chan in candidates:
        if goal == "channel":
            results.add(simulate(actions, mode, trig, chan))
        else:
            st = {}
            tx = {"main": None, "other": None}
            for act in actions:
                op = act.get("op")
                conn = act.get("connection", "main")
                if op == "begin":
                    tx[conn] = dict(st)
                elif op == "commit":
                    if tx[conn] is not None:
                        st = tx[conn]
                        tx[conn] = None
                elif op == "rollback":
                    tx[conn] = None
                else:
                    key = act.get("key")
                    value = act.get("value", 0)
                    if tx[conn] is not None:
                        saved = st
                        st = tx[conn]
                        if op == "put":
                            if mode == "ignore":
                                if key not in st:
                                    st[key] = value
                            else:
                                st[key] = value
                        elif op == "update":
                            if key in st:
                                st[key] = value
                        elif op == "delete":
                            if key in st:
                                del st[key]
                        tx[conn] = st
                        st = saved
                    else:
                        if op == "put":
                            if mode == "ignore":
                                if key not in st:
                                    st[key] = value
                            else:
                                st[key] = value
                        elif op == "update":
                            if key in st:
                                st[key] = value
                        elif op == "delete":
                            if key in st:
                                del st[key]
            if goal == "committed_count":
                results.add(len(st))
            else:
                results.add(sum(st.values()))

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}

def investigate(context, acquire):
    receipts = acquire("history")

    def run(actions, mode, trig, chan):
        state = {}
        tx = {"main": None, "other": None}
        total = {"main": 0, "other": 0}
        last = {"main": 0, "other": 0}
        log = [0]

        def write(conn, op, key, value):
            if op == "put":
                if mode == "ignore":
                    if key in state:
                        return 0
                    state[key] = value
                    n = 1
                else:
                    state[key] = value
                    n = 1
                if trig:
                    log[0] += 1
                return n
            if op == "update":
                if key in state:
                    state[key] = value
                    n = 1
                else:
                    n = 0
                if trig and n > 0:
                    log[0] += 1
                return n
            if op == "delete":
                if key in state:
                    del state[key]
                    return 1
                return 0
            return 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                tx[conn] = dict(state)
            elif op == "commit":
                if tx[conn] is not None:
                    state = tx[conn]
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            else:
                key = act.get("key")
                value = act.get("value", 0)
                if tx[conn] is not None:
                    saved = state
                    state = tx[conn]
                    n = write(conn, op, key, value)
                    tx[conn] = state
                    state = saved
                else:
                    n = write(conn, op, key, value)
                total[conn] += n
                last[conn] = n

        if chan == "changes":
            return last["main"]
        if chan == "total_main":
            return total["main"]
        return total["main"] + total["other"]

