                    state = tx[conn]
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            else:
                key = act.get("key")
                value = act.get("value", 0)
                if tx[conn] is not None:
                    saved = state
                    state = tx[conn]
                    if op == "put":
                        if mode == "ignore":
                            if key not in state:
                                state[key] = value
                        else:
                            state[key] = value
                    elif op == "update":
                        if key in state:
                            state[key] = value
                    elif op == "delete":
                        if key in state:
                            del state[key]
                    tx[conn] = state
                    state = saved
                else:
