    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}

def investigate(context, acquire):
    receipts = acquire("history")
    if not receipts:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        # put_mode: 0=IGNORE, 1=REPLACE, 2=UPSERT
        # trigger: bool, AFTER INSERT trigger logging one row
        # channel_mode: 0=changes(), 1=total_changes main, 2=total_changes main+other
        main = {}
        other = {}
        log = 0
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        in_tx = False
        tx_conn = None
        last_changes = 0

        def do_put(conn, key, value):
            nonlocal log, main_changes, other_changes, main_total, other_total, last_changes
            d = main if conn == "main" else other
            changed = 0
            if put_mode == 0:
                if key not in d:
                    d[key] = value
                    changed = 1
            elif put_mode == 1:
                d[key] = value
                changed = 1
            else:
                if key in d:
                    if d[key] != value:
                        d[key] = value
                        changed = 1
                else:
                    d[key] = value
                    changed = 1
            if changed and trigger:
                log += 1
            if conn == "main":
                main_changes += changed
                main_total += changed
            else:
                other_changes += changed
                other_total += changed
            last_changes = changed

        def do_update(conn, key, value):
            nonlocal log, main_changes, other_changes, main_total, other_total, last_changes
            d = main if conn == "main" else other
            changed = 0
            if key in d:
                if d[key] != value:
                    d[key] = value
                    changed = 1
            if changed and trigger:
                log += 1
            if conn == "main":
                main_changes += changed
                main_total += changed
            else:
                other_changes += changed
                other_total += changed
            last_changes = changed

        def do_delete(conn, key):
            nonlocal log, main_changes, other_changes, main_total, other_total, last_changes
            d = main if conn == "main" else other
            changed = 0
            if key in d:
                del d[key]
                changed = 1
            if conn == "main":
                main_changes += changed
                main_total += changed
            else:
                other_changes += changed
                other_total += changed
            last_changes = changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                in_tx = True
                tx_conn = conn
            elif op == "commit":
                in_tx = False
                tx_conn = None
            elif op == "rollback":
                in_tx = False
                tx_conn = None
            elif op == "put":
                do_put(conn, act.get("key"), act.get("value"))
            elif op == "update":
                do_update(conn, act.get("key"), act.get("value"))
            elif op == "delete":
                do_delete(conn, act.get("key"))

        if channel_mode == 0:
            ch = last_changes
        elif channel_mode == 1:
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(main), sum(main.values())

    candidates = []
    for put_mode in range(3):
        for trigger in (False, True):
            for channel_mode in range(3):
                ok = True
                for r in receipts:
                    ch, cnt, sm = simulate(r["actions"], put_mode, trigger, channel_mode)
                    obs = r["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cnt)
        elif goal == "committed_sum":
            results.append(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}

